224	   */
225	  static stateProperties: string[] = stateProperties;
226	
227	  /**
228	   * List of properties to consider when checking if cache needs refresh
229	   * Those properties are checked by
230	   * calls to Object.set(key, value). If the key is in this list, the object is marked as dirty
231	   * and refreshed at the next render
232	   * @type Array
233	   */
234	  static cacheProperties: string[] = cacheProperties;
