236	  /**
237	   * When set to `true`, object's cache will be rerendered next render call.
238	   * since 1.7.0
239	   * @type Boolean
240	   * @default true
241	   */
242	  declare dirty: boolean;
243	
244	  /**
245	   * Quick access for the _cacheCanvas rendering context
246	   * This is part of the objectCaching feature
247	   * since 1.7.0
248	   * @type boolean
249	   * @default undefined
250	   * @private
251	   */
252	  _cacheContext: CanvasRenderingContext2D | null = null;
253	
254	  /**
255	   * A reference to the HTMLCanvasElement that is used to contain the cache of the object
256	   * this canvas element is resized and cleared as needed
257	   * Is marked private, you can read it, don't use it since it is handled by fabric
258	   * since 1.7.0
259	   * @type HTMLCanvasElement
260	   * @default undefined
261	   * @private
262	   */
263	  declare _cacheCanvas?: HTMLCanvasElement;
264	
265	  /**
266	   * zoom level used on the cacheCanvas to draw the cache, X axe
267	   * since 1.7.0
268	   * @type number
269	   * @default undefined
270	   * @private
271	   */
272	  declare zoomX?: number;
273	
274	  /**
275	   * zoom level used on the cacheCanvas to draw the cache, Y axe
276	   * since 1.7.0
277	   * @type number
278	   * @default undefined
279	   * @private
280	   */
281	  declare zoomY?: number;
282	
283	  /**
284	   * zoom level used on the cacheCanvas to draw the cache, Y axe
285	   * since 1.7.0
286	   * @type number
287	   * @default undefined
288	   * @private
289	   */
290	  declare cacheTranslationX?: number;
291	
292	  /**
293	   * translation of the cacheCanvas away from the center, for subpixel accuracy and crispness
294	   * since 1.7.0
295	   * @type number
296	   * @default undefined
297	   * @private
298	   */
299	  declare cacheTranslationY?: number;
300	
301	  /**
302	   * A reference to the parent of the object, usually a Group
303	   * @type number
304	   * @default undefined
305	   * @private
306	   */
307	  declare group?: Group;
308	
309	  /**
310	   * Indicate if the object is sitting on a cache dedicated to it
311	   * or is part of a larger cache for many object ( a group for example)
312	   * @type number
313	   * @default undefined
314	   * @private
315	   */
316	  declare ownCaching?: boolean;
317	
318	  /**
319	   * Private. indicates if the object inside a group is on a transformed context or not
320	   * or is part of a larger cache for many object ( a group for example)
321	   * @type boolean
322	   * @default undefined
323	   * @private
324	   */
