333	  /**
334	   * The class type.
335	   * This is used for serialization and deserialization purposes and internally it can be used
336	   * to identify classes.
337	   * When we transform a class in a plain JS object we need a way to recognize which class it was,
338	   * and the type is the way we do that. It has no other purposes and you should not give one.
339	   * Hard to reach on instances and please do not use to drive instance's logic (this.constructor.type).
340	   * To idenfity a class use instanceof class ( instanceof Rect ).
341	   * We do not do that in fabricJS code because we want to try to have code splitting possible.
342	   */
343	  static type = 'FabricObject';
344	
345	  /**
346	   * Legacy identifier of the class. Prefer using utils like isType or instanceOf
347	   * Will be removed in fabric 7 or 8.
348	   * The setter exists to avoid type errors in old code and possibly current deserialization code.
349	   * DO NOT build new code around this type value
350	   * @TODO add sustainable warning message
351	   * @type string
352	   * @deprecated
353	   */
354	  get type() {
355	    const name = (this.constructor as typeof FabricObject).type;
356	    if (name === 'FabricObject') {
357	      return 'object';
358	    }
359	    return name.toLowerCase();
360	  }
