366	  /**
367	   * Constructor
368	   * @param {Object} [options] Options object
369	   */
370	  constructor(options?: Props) {
371	    super();
372	    Object.assign(this, FabricObject.ownDefaults);
373	    this.setOptions(options);
374	  }
375	
376	  /**
377	   * Create a the canvas used to keep the cached copy of the object
378	   * @private
379	   */
380	  _createCacheCanvas() {
381	    this._cacheCanvas = createCanvasElement();
382	    this._cacheContext = this._cacheCanvas.getContext('2d');
383	    this._updateCacheCanvas();
384	    // if canvas gets created, is empty, so dirty.
385	    this.dirty = true;
386	  }
387	
388	  /**
389	   * Limit the cache dimensions so that X * Y do not cross config.perfLimitSizeTotal
390	   * and each side do not cross fabric.cacheSideLimit
391	   * those numbers are configurable so that you can get as much detail as you want
392	   * making bargain with performances.
393	   * It mutates the input object dims.
394	   * @param {TCacheCanvasDimensions} dims
395	   * @return {TCacheCanvasDimensions} dims
396	   */
397	  _limitCacheSize(
398	    dims: TCacheCanvasDimensions & { capped?: boolean },
399	  ): TCacheCanvasDimensions & { capped?: boolean } {
400	    const width = dims.width,
401	      height = dims.height,
402	      max = config.maxCacheSideLimit,
403	      min = config.minCacheSideLimit;
404	    if (
405	      width <= max &&
406	      height <= max &&
407	      width * height <= config.perfLimitSizeTotal
408	    ) {
409	      if (width < min) {
410	        dims.width = min;
411	      }
412	      if (height < min) {
413	        dims.height = min;
414	      }
415	      return dims;
416	    }
417	    const ar = width / height,
418	      [limX, limY] = cache.limitDimsByArea(ar),
419	      x = capValue(min, limX, max),
420	      y = capValue(min, limY, max);
421	    if (width > x) {
422	      dims.zoomX /= width / x;
423	      dims.width = x;
424	      dims.capped = true;
425	    }
426	    if (height > y) {
427	      dims.zoomY /= height / y;
428	      dims.height = y;
429	      dims.capped = true;
430	    }
431	    return dims;
432	  }
433	
434	  /**
435	   * Return the dimension and the zoom level needed to create a cache canvas
436	   * big enough to host the object to be cached.
437	   * @private
438	   * @return {TCacheCanvasDimensions} Informations about the object to be cached
439	   */
440	  _getCacheCanvasDimensions(): TCacheCanvasDimensions {
441	    const objectScale = this.getTotalObjectScaling(),
442	      // calculate dimensions without skewing
443	      dim = this._getTransformedDimensions({ skewX: 0, skewY: 0 }),
444	      neededX = (dim.x * objectScale.x) / this.scaleX,
445	      neededY = (dim.y * objectScale.y) / this.scaleY;
446	    return {
447	      // for sure this ALIASING_LIMIT is slightly creating problem
448	      // in situation in which the cache canvas gets an upper limit
449	      // also objectScale contains already scaleX and scaleY
450	      width: Math.ceil(neededX + ALIASING_LIMIT),
451	      height: Math.ceil(neededY + ALIASING_LIMIT),
452	      zoomX: objectScale.x,
453	      zoomY: objectScale.y,
454	      x: neededX,
455	      y: neededY,
456	    };
457	  }
458	
459	  /**
460	   * Update width and height of the canvas for cache
461	   * returns true or false if canvas needed resize.
462	   * @private
463	   * @return {Boolean} true if the canvas has been resized
464	   */
465	  _updateCacheCanvas() {
466	    const canvas = this._cacheCanvas!,
467	      context = this._cacheContext,
468	      { width, height, zoomX, zoomY, x, y } = this._limitCacheSize(
469	        this._getCacheCanvasDimensions(),
470	      ),
471	      dimensionsChanged = width !== canvas.width || height !== canvas.height,
472	      zoomChanged = this.zoomX !== zoomX || this.zoomY !== zoomY;
473	
474	    if (!canvas || !context) {
475	      return false;
476	    }
477	
478	    const shouldRedraw = dimensionsChanged || zoomChanged;
479	
480	    if (shouldRedraw) {
481	      if (width !== canvas.width || height !== canvas.height) {
482	        canvas.width = width;
483	        canvas.height = height;
484	      } else {
485	        context.setTransform(1, 0, 0, 1, 0, 0);
486	        context.clearRect(0, 0, canvas.width, canvas.height);
487	      }
488	      const drawingWidth = x / 2;
489	      const drawingHeight = y / 2;
490	      this.cacheTranslationX =
491	        Math.round(canvas.width / 2 - drawingWidth) + drawingWidth;
492	      this.cacheTranslationY =
493	        Math.round(canvas.height / 2 - drawingHeight) + drawingHeight;
494	      context.translate(this.cacheTranslationX, this.cacheTranslationY);
495	      context.scale(zoomX, zoomY);
496	      this.zoomX = zoomX;
497	      this.zoomY = zoomY;
498	      return true;
499	    }
500	    return false;
501	  }
502	
503	  /**
504	   * Sets object's properties from options, for class constructor only.
505	   * Needs to be overridden for different defaults.
506	   * @protected
507	   * @param {Object} [options] Options object
508	   */
509	  protected setOptions(options: Record<string, any> = {}) {
510	    this._setOptions(options);
511	  }
512	
513	  /**
514	   * Transforms context when rendering an object
515	   * @param {CanvasRenderingContext2D} ctx Context
516	   */
517	  transform(ctx: CanvasRenderingContext2D) {
518	    const needFullTransform =
519	      (this.group && !this.group._transformDone) ||
520	      (this.group && this.canvas && ctx === (this.canvas as Canvas).contextTop);
521	    const m = this.calcTransformMatrix(!needFullTransform);
522	    ctx.transform(m[0], m[1], m[2], m[3], m[4], m[5]);
523	  }
524	
525	  /**
526	   * Return the object scale factor counting also the group scaling
527	   * @return {Point}
528	   */
529	  getObjectScaling() {
530	    // if the object is a top level one, on the canvas, we go for simple aritmetic
531	    // otherwise the complex method with angles will return approximations and decimals
532	    // and will likely kill the cache when not needed
533	    // https://github.com/fabricjs/fabric.js/issues/7157
534	    if (!this.group) {
535	      return new Point(Math.abs(this.scaleX), Math.abs(this.scaleY));
536	    }
537	    // if we are inside a group total zoom calculation is complex, we defer to generic matrices
538	    const options = qrDecompose(this.calcTransformMatrix());
539	    return new Point(Math.abs(options.scaleX), Math.abs(options.scaleY));
540	  }
541	
542	  /**
543	   * Return the object scale factor counting also the group scaling, zoom and retina
544	   * @return {Object} object with scaleX and scaleY properties
545	   */
546	  getTotalObjectScaling() {
547	    const scale = this.getObjectScaling();
548	    if (this.canvas) {
549	      const zoom = this.canvas.getZoom();
550	      const retina = this.getCanvasRetinaScaling();
551	      return scale.scalarMultiply(zoom * retina);
552	    }
553	    return scale;
554	  }
555	
556	  /**
557	   * Return the object opacity counting also the group property
558	   * @return {Number}
559	   */
560	  getObjectOpacity() {
561	    let opacity = this.opacity;
562	    if (this.group) {
563	      opacity *= this.group.getObjectOpacity();
564	    }
565	    return opacity;
566	  }
567	
568	  /**
569	   * Makes sure the scale is valid and modifies it if necessary
570	   * @todo: this is a control action issue, not a geometry one
571	   * @private
572	   * @param {Number} value, unconstrained
573	   * @return {Number} constrained value;
574	   */
575	  _constrainScale(value: number): number {
576	    if (Math.abs(value) < this.minScaleLimit) {
577	      if (value < 0) {
578	        return -this.minScaleLimit;
579	      } else {
580	        return this.minScaleLimit;
581	      }
582	    } else if (value === 0) {
583	      return 0.0001;
584	    }
585	    return value;
586	  }
587	
588	  /**
589	   * Handles setting values on the instance and handling internal side effects
590	   * @protected
591	   * @param {String} key
592	   * @param {*} value
593	   */
594	  _set(key: string, value: any) {
595	    if (key === SCALE_X || key === SCALE_Y) {
596	      value = this._constrainScale(value);
597	    }
598	    if (key === SCALE_X && value < 0) {
599	      this.flipX = !this.flipX;
600	      value *= -1;
601	    } else if (key === 'scaleY' && value < 0) {
602	      this.flipY = !this.flipY;
603	      value *= -1;
604	      // i don't like this automatic initialization here
605	    } else if (key === 'shadow' && value && !(value instanceof Shadow)) {
606	      value = new Shadow(value);
607	    }
608	
609	    const isChanged = this[key as keyof this] !== value;
610	    this[key as keyof this] = value;
611	
612	    // invalidate caches
613	    if (
614	      isChanged &&
615	      (this.constructor as typeof FabricObject).cacheProperties.includes(key)
616	    ) {
617	      this.dirty = true;
618	    }
619	    // a dirty child makes the parent dirty.
620	    // but a non dirty child does not make the parent not dirty.
621	    // the parent could be dirty for some other reason.
622	    this.parent &&
623	      (this.dirty ||
624	        (isChanged &&
625	          (this.constructor as typeof FabricObject).stateProperties.includes(
626	            key,
627	          ))) &&
628	      this.parent._set('dirty', true);
629	
630	    return this;
631	  }
632	
633	  /**
634	   * return if the object would be visible in rendering
635	   * @return {Boolean}
636	   */
637	  isNotVisible() {
638	    return (
639	      this.opacity === 0 ||
640	      (!this.width && !this.height && this.strokeWidth === 0) ||
641	      !this.visible
642	    );
643	  }
644	
645	  /**
646	   * Renders an object on a specified context
647	   * @param {CanvasRenderingContext2D} ctx Context to render on
648	   */
649	  render(ctx: CanvasRenderingContext2D) {
650	    // do not render if width/height are zeros or object is not visible
651	    if (this.isNotVisible()) {
652	      return;
653	    }
654	    if (
655	      this.canvas &&
656	      this.canvas.skipOffscreen &&
657	      !this.group &&
658	      !this.isOnScreen()
659	    ) {
660	      return;
661	    }
662	    ctx.save();
663	    this._setupCompositeOperation(ctx);
664	    this.drawSelectionBackground(ctx);
665	    this.transform(ctx);
666	    this._setOpacity(ctx);
667	    this._setShadow(ctx);
668	    if (this.shouldCache()) {
669	      (this as TCachedFabricObject).renderCache();
670	      (this as TCachedFabricObject).drawCacheOnCanvas(ctx);
671	    } else {
672	      this._removeCacheCanvas();
673	      this.drawObject(ctx, false, {});
674	      this.dirty = false;
675	    }
676	    ctx.restore();
677	  }
678	
679	  drawSelectionBackground(_ctx: CanvasRenderingContext2D) {
680	    /* no op */
681	  }
682	
683	  renderCache(this: TCachedFabricObject, options?: any) {
684	    options = options || {};
685	    if (!this._cacheCanvas || !this._cacheContext) {
686	      this._createCacheCanvas();
687	    }
688	    if (this.isCacheDirty() && this._cacheContext) {
689	      const { zoomX, zoomY, cacheTranslationX, cacheTranslationY } = this;
690	      const { width, height } = this._cacheCanvas;
691	      this.drawObject(this._cacheContext, options.forClipping, {
692	        zoomX,
693	        zoomY,
694	        cacheTranslationX,
695	        cacheTranslationY,
696	        width,
697	        height,
698	        parentClipPaths: [],
699	      });
700	      this.dirty = false;
701	    }
702	  }
703	
