843	  private createClipPathLayer(
844	    this: TCachedFabricObject,
845	    clipPath: FabricObject,
846	    context: DrawContext,
847	  ) {
848	    const canvas = createCanvasElementFor(context as TSize);
849	    const ctx = canvas.getContext('2d')!;
850	    ctx.translate(context.cacheTranslationX, context.cacheTranslationY);
851	    ctx.scale(context.zoomX, context.zoomY);
852	    clipPath._cacheCanvas = canvas;
853	    context.parentClipPaths.forEach((prevClipPath) => {
854	      prevClipPath.transform(ctx);
855	    });
856	    context.parentClipPaths.push(clipPath);
857	    if (clipPath.absolutePositioned) {
858	      const m = invertTransform(this.calcTransformMatrix());
859	      ctx.transform(m[0], m[1], m[2], m[3], m[4], m[5]);
860	    }
861	    clipPath.transform(ctx);
862	    clipPath.drawObject(ctx, true, context);
863	    return canvas;
864	  }
