870	   */
871	  _drawClipPath(
872	    ctx: CanvasRenderingContext2D,
873	    clipPath: FabricObject | undefined,
874	    context: DrawContext,
875	  ) {
876	    if (!clipPath) {
877	      return;
878	    }
879	    // needed to setup _transformDone
880	    // TODO find a better solution?
881	    clipPath._transformDone = true;
882	    const canvas = (this as TCachedFabricObject).createClipPathLayer(
883	      clipPath,
884	      context,
885	    );
886	    this.drawClipPathOnCache(ctx, clipPath, canvas);
