911	    if (this.isNotVisible()) {
912	      return false;
913	    }
914	    const canvas = this._cacheCanvas;
915	    const ctx = this._cacheContext;
916	    if (canvas && ctx && !skipCanvas && this._updateCacheCanvas()) {
917	      // in this case the context is already cleared.
918	      return true;
919	    } else {
920	      if (this.dirty || (this.clipPath && this.clipPath.absolutePositioned)) {
921	        if (canvas && ctx && !skipCanvas) {
922	          ctx.save();
923	          ctx.setTransform(1, 0, 0, 1, 0, 0);
924	          ctx.clearRect(0, 0, canvas.width, canvas.height);
925	          ctx.restore();
