963	  _setStrokeStyles(
964	    ctx: CanvasRenderingContext2D,
965	    decl: Pick<
966	      this,
967	      | 'stroke'
968	      | 'strokeWidth'
969	      | 'strokeLineCap'
970	      | 'strokeDashOffset'
971	      | 'strokeLineJoin'
972	      | 'strokeMiterLimit'
