982	      if (isFiller(stroke)) {
983	        if (
984	          (stroke as Gradient<'linear'>).gradientUnits === 'percentage' ||
985	          (stroke as Gradient<'linear'>).gradientTransform ||
986	          (stroke as Pattern).patternTransform
