1035	  /**
1036	   * @private
1037	   * @param {CanvasRenderingContext2D} ctx Context to render on
1038	   */
1039	  _setShadow(ctx: CanvasRenderingContext2D) {
1040	    if (!this.shadow) {
1041	      return;
1042	    }
1043	
1044	    const shadow = this.shadow,
1045	      canvas = this.canvas,
1046	      retinaScaling = this.getCanvasRetinaScaling(),
1047	      [sx, , , sy] = canvas?.viewportTransform || iMatrix,
1048	      multX = sx * retinaScaling,
1049	      multY = sy * retinaScaling,
1050	      scaling = shadow.nonScaling ? new Point(1, 1) : this.getObjectScaling();
