1075	  /**
1076	   * @private
1077	   * @param {CanvasRenderingContext2D} ctx Context to render on
1078	   * @param {TFiller} filler {@link Pattern} or {@link Gradient}
1079	   */
1080	  _applyPatternGradientTransform(
1081	    ctx: CanvasRenderingContext2D,
1082	    filler: TFiller,
1083	  ) {
1084	    if (!isFiller(filler)) {
1085	      return { offsetX: 0, offsetY: 0 };
1086	    }
1087	    const t =
1088	      (filler as Gradient<'linear'>).gradientTransform ||
1089	      (filler as Pattern).patternTransform;
1090	    const offsetX = -this.width / 2 + filler.offsetX || 0,
1091	      offsetY = -this.height / 2 + filler.offsetY || 0;
1092	
1093	    if ((filler as Gradient<'linear'>).gradientUnits === 'percentage') {
1094	      ctx.transform(this.width, 0, 0, this.height, offsetX, offsetY);
1095	    } else {
1096	      ctx.transform(1, 0, 0, 1, offsetX, offsetY);
1097	    }
1098	    if (t) {
1099	      ctx.transform(t[0], t[1], t[2], t[3], t[4], t[5]);
1100	    }
1101	    return { offsetX: offsetX, offsetY: offsetY };
1102	  }
