1172	  /**
1173	   * This function try to patch the missing gradientTransform on canvas gradients.
1174	   * transforming a context to transform the gradient, is going to transform the stroke too.
1175	   * we want to transform the gradient but not the stroke operation, so we create
1176	   * a transformed gradient on a pattern and then we use the pattern instead of the gradient.
1177	   * this method has drawbacks: is slow, is in low resolution, needs a patch for when the size
1178	   * is limited.
1179	   * @private
1180	   * @param {CanvasRenderingContext2D} ctx Context to render on
1181	   * @param {Gradient} filler
1182	   */
1183	  _applyPatternForTransformedGradient(
1184	    ctx: CanvasRenderingContext2D,
1185	    filler: TFiller,
1186	  ) {
1187	    const dims = this._limitCacheSize(this._getCacheCanvasDimensions()),
1188	      retinaScaling = this.getCanvasRetinaScaling(),
1189	      width = dims.x / this.scaleX / retinaScaling,
1190	      height = dims.y / this.scaleY / retinaScaling,
1191	      pCanvas = createCanvasElementFor({
1192	        // in case width and height are less than 1px, we have to round up.
1193	        // since the pattern is no-repeat, this is fine
1194	        width: Math.ceil(width),
1195	        height: Math.ceil(height),
1196	      });
1197	
1198	    const pCtx = pCanvas.getContext('2d');
1199	    if (!pCtx) {
1200	      return;
1201	    }
1202	    pCtx.beginPath();
1203	    pCtx.moveTo(0, 0);
1204	    pCtx.lineTo(width, 0);
1205	    pCtx.lineTo(width, height);
1206	    pCtx.lineTo(0, height);
1207	    pCtx.closePath();
1208	    pCtx.translate(width / 2, height / 2);
1209	    pCtx.scale(
1210	      dims.zoomX / this.scaleX / retinaScaling,
1211	      dims.zoomY / this.scaleY / retinaScaling,
1212	    );
1213	    this._applyPatternGradientTransform(pCtx, filler);
1214	    pCtx.fillStyle = filler.toLive(ctx)!;
1215	    pCtx.fill();
1216	    ctx.translate(
1217	      -this.width / 2 - this.strokeWidth / 2,
1218	      -this.height / 2 - this.strokeWidth / 2,
1219	    );
1220	    ctx.scale(
1221	      (retinaScaling * this.scaleX) / dims.zoomX,
1222	      (retinaScaling * this.scaleY) / dims.zoomY,
1223	    );
1224	    ctx.strokeStyle = pCtx.createPattern(pCanvas, 'no-repeat') ?? '';
1225	  }
