1513	  /**
1514	   * Animates object's properties
1515	   * @param {Record<string, number | number[] | TColorArg>} animatable map of keys and end values
1516	   * @param {Partial<AnimationOptions<T>>} options
1517	   * @see {@link http://fabric5.fabricjs.com/fabric-intro-part-2#animation}
1518	   * @return {Record<string, TAnimation<T>>} map of animation contexts
1519	   *
1520	   * As object — multiple properties
1521	   *
1522	   * object.animate({ left: ..., top: ... });
1523	   * object.animate({ left: ..., top: ... }, { duration: ... });
1524	   */
1525	  animate<T extends number | number[] | TColorArg>(
1526	    animatable: Record<string, T>,
1527	    options?: Partial<AnimationOptions<T>>,
1528	  ): Record<string, TAnimation<T>> {
1529	    return Object.entries(animatable).reduce(
1530	      (acc, [key, endValue]) => {
1531	        acc[key] = this._animate(key, endValue, options);
1532	        return acc;
1533	      },
1534	      {} as Record<string, TAnimation<T>>,
1535	    );
