1538	  /**
1539	   * @private
1540	   * @param {String} key Property to animate
1541	   * @param {String} to Value to animate to
1542	   * @param {Object} [options] Options object
1543	   */
1544	  _animate<T extends number | number[] | TColorArg>(
1545	    key: string,
1546	    endValue: T,
1547	    options: Partial<AnimationOptions<T>> = {},
1548	  ): TAnimation<T> {
1549	    const path = key.split('.');
1550	    const propIsColor = (
1551	      this.constructor as typeof FabricObject
1552	    ).colorProperties.includes(path[path.length - 1]);
1553	    const { abort, startValue, onChange, onComplete } = options;
1554	    const animationOptions = {
1555	      ...options,
1556	      target: this,
1557	      // path.reduce... is the current value in case start value isn't provided
1558	      startValue:
1559	        startValue ?? path.reduce((deep: any, key) => deep[key], this),
1560	      endValue,
1561	      abort: abort?.bind(this),
1562	      onChange: (
1563	        value: number | number[] | string,
1564	        valueProgress: number,
1565	        durationProgress: number,
1566	      ) => {
1567	        path.reduce((deep: Record<string, any>, key, index) => {
1568	          if (index === path.length - 1) {
1569	            deep[key] = value;
1570	          }
1571	          return deep[key];
1572	        }, this);
1573	        onChange &&
1574	          // @ts-expect-error generic callback arg0 is wrong
1575	          onChange(value, valueProgress, durationProgress);
1576	      },
1577	      onComplete: (
1578	        value: number | number[] | string,
1579	        valueProgress: number,
1580	        durationProgress: number,
1581	      ) => {
1582	        this.setCoords();
1583	        onComplete &&
1584	          // @ts-expect-error generic callback arg0 is wrong
1585	          onComplete(value, valueProgress, durationProgress);
1586	      },
1587	    } as AnimationOptions<T>;
1588	
1589	    return (
1590	      propIsColor
1591	        ? animateColor(animationOptions as ColorAnimationOptions)
1592	        : animate(
1593	            animationOptions as ValueAnimationOptions | ArrayAnimationOptions,
1594	          )
1595	    ) as TAnimation<T>;
1596	  }
