1606	  /**
1607	   * Checks if object is descendant of target
1608	   * Should be used instead of {@link Group.contains} or {@link StaticCanvas.contains} for performance reasons
1609	   * @param {TAncestor} target
1610	   * @returns {boolean}
1611	   */
1612	  isDescendantOf(target: TAncestor): boolean {
1613	    const { parent, group } = this;
1614	    return (
1615	      parent === target ||
1616	      group === target ||
1617	      // walk up
1618	      (!!parent && parent.isDescendantOf(target)) ||
1619	      (!!group && group !== parent && group.isDescendantOf(target))
1620	    );
1621	  }
