1623	  /**
1624	   * @returns {Ancestors} ancestors (excluding `ActiveSelection`) from bottom to top
1625	   */
1626	  getAncestors(): Ancestors {
1627	    const ancestors: TAncestor[] = [];
1628	    // eslint-disable-next-line @typescript-eslint/no-this-alias
1629	    let parent: TAncestor | undefined = this;
1630	    do {
1631	      parent = parent.parent;
1632	      parent && ancestors.push(parent);
1633	    } while (parent);
1634	    return ancestors as Ancestors;
1635	  }
