1637	  /**
1638	   * Compare ancestors
1639	   *
1640	   * @param {StackedObject} other
1641	   * @returns {AncestryComparison} an object that represent the ancestry situation.
1642	   */
1643	  findCommonAncestors<T extends this>(other: T): AncestryComparison {
1644	    if (this === other) {
1645	      return {
1646	        fork: [],
1647	        otherFork: [],
1648	        common: [this, ...this.getAncestors()],
1649	      } as AncestryComparison;
1650	    }
1651	    const ancestors = this.getAncestors();
1652	    const otherAncestors = other.getAncestors();
1653	    //  if `this` has no ancestors and `this` is top ancestor of `other` we must handle the following case
1654	    if (
1655	      ancestors.length === 0 &&
1656	      otherAncestors.length > 0 &&
1657	      this === otherAncestors[otherAncestors.length - 1]
1658	    ) {
1659	      return {
1660	        fork: [],
1661	        otherFork: [
1662	          other,
1663	          ...otherAncestors.slice(0, otherAncestors.length - 1),
1664	        ],
1665	        common: [this],
1666	      } as AncestryComparison;
1667	    }
1668	    //  compare ancestors
1669	    for (let i = 0, ancestor; i < ancestors.length; i++) {
1670	      ancestor = ancestors[i];
1671	      if (ancestor === other) {
1672	        return {
1673	          fork: [this, ...ancestors.slice(0, i)],
1674	          otherFork: [],
1675	          common: ancestors.slice(i),
1676	        } as AncestryComparison;
1677	      }
1678	      for (let j = 0; j < otherAncestors.length; j++) {
1679	        if (this === otherAncestors[j]) {
1680	          return {
1681	            fork: [],
1682	            otherFork: [other, ...otherAncestors.slice(0, j)],
1683	            common: [this, ...ancestors],
1684	          } as AncestryComparison;
1685	        }
1686	        if (ancestor === otherAncestors[j]) {
1687	          return {
1688	            fork: [this, ...ancestors.slice(0, i)],
1689	            otherFork: [other, ...otherAncestors.slice(0, j)],
1690	            common: ancestors.slice(i),
1691	          } as AncestryComparison;
1692	        }
1693	      }
1694	    }
1695	    // nothing shared
1696	    return {
1697	      fork: [this, ...ancestors],
1698	      otherFork: [other, ...otherAncestors],
1699	      common: [],
1700	    } as AncestryComparison;
1701	  }
