1703	  /**
1704	   *
1705	   * @param {StackedObject} other
1706	   * @returns {boolean}
1707	   */
1708	  hasCommonAncestors<T extends this>(other: T): boolean {
1709	    const commonAncestors = this.findCommonAncestors(other);
1710	    return commonAncestors && !!commonAncestors.common.length;
1711	  }
1712	
1713	  /**
1714	   *
1715	   * @param {FabricObject} other object to compare against
1716	   * @returns {boolean | undefined} if objects do not share a common ancestor or they are strictly equal it is impossible to determine which is in front of the other; in such cases the function returns `undefined`
1717	   */
1718	  isInFrontOf<T extends this>(other: T): boolean | undefined {
1719	    if (this === other) {
1720	      return undefined;
1721	    }
1722	    const ancestorData = this.findCommonAncestors(other);
1723	
1724	    if (ancestorData.fork.includes(other as any)) {
1725	      return true;
1726	    }
1727	    if (ancestorData.otherFork.includes(this as any)) {
1728	      return false;
1729	    }
1730	    // if there isn't a common ancestor, we take the canvas.
1731	    // if there is no canvas, there is nothing to compare
1732	    const firstCommonAncestor = ancestorData.common[0] || this.canvas;
1733	    if (!firstCommonAncestor) {
1734	      return undefined;
1735	    }
1736	    const headOfFork = ancestorData.fork.pop(),
1737	      headOfOtherFork = ancestorData.otherFork.pop(),
1738	      thisIndex = (firstCommonAncestor as TCollection)._objects.indexOf(
1739	        headOfFork as any,
1740	      ),
1741	      otherIndex = (firstCommonAncestor as TCollection)._objects.indexOf(
1742	        headOfOtherFork as any,
1743	      );
1744	    return thisIndex > -1 && thisIndex > otherIndex;
1745	  }
