1870	    return pickBy(object, (value, key) => {
1871	      if (key === LEFT || key === TOP || key === 'type') {
1872	        return true;
1873	      }
1874	      const baseValue = baseValues[key];
1875	      return (
1876	        value !== baseValue &&
1877	        // basically a check for [] === []
1878	        !(
1879	          Array.isArray(value) &&
1880	          Array.isArray(baseValue) &&
1881	          value.length === 0 &&
1882	          baseValue.length === 0
1883	        )
1884	      );
